CREATE TABLE sys_user (id BIGINT PRIMARY KEY, username VARCHAR(64) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(32) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE class_room (id BIGINT PRIMARY KEY, name VARCHAR(120) NOT NULL, grade VARCHAR(32) NOT NULL, teacher_id BIGINT NOT NULL, is_demo BOOLEAN NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, class_id BIGINT NOT NULL, student_no VARCHAR(32) NOT NULL, name VARCHAR(80) NOT NULL, gender VARCHAR(16), status VARCHAR(16) DEFAULT 'ACTIVE', archived_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE growth_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, dimension VARCHAR(16) NOT NULL, score DECIMAL(5,2) NOT NULL, title VARCHAR(160) NOT NULL, detail VARCHAR(500), occurred_on DATE NOT NULL, source VARCHAR(64) NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE score_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, student_id BIGINT NOT NULL, subject VARCHAR(40) NOT NULL, exam_name VARCHAR(120) NOT NULL, score DECIMAL(6,2) NOT NULL, full_score DECIMAL(6,2) NOT NULL, occurred_on DATE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attendance_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, attendance_date DATE NOT NULL, status VARCHAR(16) NOT NULL, note VARCHAR(200), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,attendance_date));
CREATE TABLE behavior_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, category VARCHAR(40) NOT NULL, score DECIMAL(5,2), occurred_on DATE NOT NULL, detail VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE skill_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, skill_name VARCHAR(120) NOT NULL, score DECIMAL(5,2) NOT NULL, level VARCHAR(32), occurred_on DATE NOT NULL, evidence VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activity_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, activity_date DATE NOT NULL, activity_type VARCHAR(80) NOT NULL, status VARCHAR(20) DEFAULT 'PARTICIPATED', detail VARCHAR(300), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dimension_evaluation (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, moral_score DECIMAL(5,2), skill_score DECIMAL(5,2), thinking_score DECIMAL(5,2), smart_score DECIMAL(5,2), evidence VARCHAR(1000), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE point_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, amount INT NOT NULL, category VARCHAR(40) NOT NULL, reason VARCHAR(160) NOT NULL, idempotency_key VARCHAR(120) UNIQUE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE point_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, amount INT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, description VARCHAR(300), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE warning_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, level VARCHAR(20) NOT NULL, rule_code VARCHAR(64) NOT NULL, summary VARCHAR(500) NOT NULL, evidence_json VARCHAR(2000) NOT NULL, status VARCHAR(20) DEFAULT 'OPEN', teacher_note VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, closed_at TIMESTAMP);
CREATE TABLE intervention_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, warning_id BIGINT, title VARCHAR(160) NOT NULL, status VARCHAR(20) DEFAULT 'DRAFT', suggestions_json VARCHAR(2000) NOT NULL, teacher_note VARCHAR(1000), review_at DATE, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE intervention_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, action VARCHAR(300) NOT NULL, status VARCHAR(20) DEFAULT 'DONE', occurred_on DATE NOT NULL, result VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE growth_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, module VARCHAR(30) NOT NULL, title VARCHAR(160) NOT NULL, description VARCHAR(500), due_on DATE NOT NULL, point_reward INT DEFAULT 0, status VARCHAR(20) DEFAULT 'PUBLISHED', created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id BIGINT NOT NULL, student_id BIGINT NOT NULL, status VARCHAR(20) DEFAULT 'ASSIGNED', completed_on DATE, teacher_note VARCHAR(500), UNIQUE(task_id,student_id));
CREATE TABLE class_target (id BIGINT PRIMARY KEY AUTO_INCREMENT, class_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, target_value DECIMAL(8,2) NOT NULL, current_value DECIMAL(8,2) DEFAULT 0, unit VARCHAR(20), status VARCHAR(20) DEFAULT 'IN_PROGRESS', created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE class_diagnosis_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, target_id BIGINT NOT NULL, measure VARCHAR(500) NOT NULL, review_result VARCHAR(500), recorded_on DATE NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_analysis (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, source VARCHAR(20) NOT NULL, request_json VARCHAR(4000), response_json VARCHAR(8000) NOT NULL, created_by BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, summary VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
